slots.setup:
const T_PHYS = 19;
const T_BRANCH_1 = 3;
const T_BRANCH_2 = 11;

slots.drawFrame:
const BRANCH_1 = 3;
const BRANCH_2 = 11;
const plateTop = 3.3;
const plateBot = -3.3;
const xL = -1.2;
const xR = 11.5;

// 平行金属板（上、下）
Draw.line([xL, plateTop], [xR, plateTop], { width: 4 });
Draw.line([xL, plateBot], [xR, plateBot], { width: 4 });

// 中轴线 MN
Draw.line([xL, 0], [xR, 0], { width: 1, dash: true });

// 板间匀强磁场（垂直纸面向里）与匀强电场（竖直向下，aux 箭头）
Draw.fieldDots(
  { x: xL + 0.25, y: plateBot + 0.3, w: xR - xL - 0.5, h: plateTop - plateBot - 0.6 },
  { symbol: 'cross', nx: 14, ny: 8 }
);
Draw.arrow([-0.7, 2.4], [0, -0.7], { category: 'aux', mag: 1 });
Draw.arrow([11.0, 2.4], [0, -0.7], { category: 'aux', mag: 1 });

// 已走过的轨迹（分段画，分支处断开）
const eps = 0.005;

const ptsA = [];
for (let tt = 0; tt < Math.min(t, BRANCH_1 - eps); tt += 0.03) {
  const s = context.at(tt);
  ptsA.push([s.ball.x, s.ball.y]);
}
if (ptsA.length > 1) Draw.trace(ptsA);

if (t > BRANCH_1) {
  const ptsB = [];
  for (let tt = BRANCH_1 + eps; tt < Math.min(t, BRANCH_2 - eps); tt += 0.03) {
    const s = context.at(tt);
    ptsB.push([s.ball.x, s.ball.y]);
  }
  if (ptsB.length > 1) Draw.trace(ptsB);
}

if (t > BRANCH_2) {
  const ptsC = [];
  for (let tt = BRANCH_2 + eps; tt <= t; tt += 0.03) {
    const s = context.at(tt);
    ptsC.push([s.ball.x, s.ball.y]);
  }
  if (ptsC.length > 1) Draw.trace(ptsC);
}

// 带电粒子
Draw.circle([state.ball.x, state.ball.y], 0.15);

slots.readouts:
// 由 analysis 运动表生成；曲线图直接读这里
const out = [];
const h = 1e-4;
const tA = Math.max(0, t - h);
const tB = Math.min(19, t + h);
const a = stateAt(tA);
const b = stateAt(tB);
const dt = (tB - tA) || 1;
out.push({ key: "ball.x", label: "ball 水平位置", value: state.ball.x, unit: 'm' });
out.push({ key: "ball.y", label: "ball 竖直位置", value: state.ball.y, unit: 'm' });
out.push({ key: "ball.vx", label: "ball 水平速度", value: (b.ball.x - a.ball.x) / dt, unit: 'm/s' });
out.push({ key: "ball.vy", label: "ball 竖直速度", value: (b.ball.y - a.ball.y) / dt, unit: 'm/s' });
return out;
